// The people's page files, bundled as text by the rules in wrangler.jsonc.
declare module "*/web/index.html" {
	const text: string;
	export default text;
}
declare module "*/web/app.css" {
	const text: string;
	export default text;
}
declare module "*/web/app.js" {
	const text: string;
	export default text;
}
